param([Parameter(Mandatory=$true)][string]$SavePath)
# Read-only explicit XML, with field presence. Does not compute capacities or execute game code.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Numeric($parent,[string]$field,[double]$default=0){$n=$parent.SelectSingleNode($field);[ordered]@{value=if($n){[double]::Parse($n.InnerText,[Globalization.CultureInfo]::InvariantCulture)}else{$default};present=($null -ne $n)}}
function Boolean($parent,[string]$field){$n=$parent.SelectSingleNode($field);[ordered]@{value=if($n){$n.InnerText -eq 'True'}else{$false};present=($null -ne $n)}}
function Stack($n){if($n.SelectSingleNode('stackCount')){[int]$n.stackCount}else{1}}
function Item($n){[ordered]@{id=[string]$n.id;def=[string]$n.def;count=(Stack $n);pos=[string]$n.pos;forbidden=([string]$n.forbidden -eq 'True');parent=$n.ParentNode.Name;container_owner=[string]$n.SelectSingleNode('ancestor::*[id and def][1]/id').InnerText}}
$map=$s.SelectSingleNode('//thing[id="Human958"]').ParentNode.ParentNode
$pawns=@($map.SelectNodes('./things/thing[def="Human"]')|ForEach-Object{
 $p=$_;$job=$p.SelectSingleNode('jobs/curJob');$driver=$p.SelectSingleNode('jobs/curDriver')
 [ordered]@{id=[string]$p.id;nick=[string]$p.name.nick;pos=[string]$p.pos;health_state_explicit=[string]$p.healthTracker.healthState;medical_care=[string]$p.playerSettings.medCare;self_tend=(Boolean $p 'playerSettings/selfTend');drafted=(Boolean $p 'drafter/drafted')
 hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{[ordered]@{id=[int]$_.loadID;class=[string]$_.Class;def=[string]$_.def;body=[string]$_.part.body;part_index=(Numeric $_ 'part/index');severity=(Numeric $_ 'severity');age_ticks=(Numeric $_ 'ageTicks');tick_added=(Numeric $_ 'tickAdded');permanent=(Boolean $_ 'isPermanent');fresh=(Boolean $_ 'isFresh');last_injury=[string]$_.lastInjury;tend_quality=(Numeric $_ 'tendQuality');tend_ticks_left=(Numeric $_ 'tendTicksLeft' -1);pain_category=[string]$_.painCategory;combat_log_entry=[string]$_.combatLogEntry}})
 job=[ordered]@{def=[string]$job.def;load_id=[int]$job.loadID;target_a=[string]$job.targetA;target_b=[string]$job.targetB;start_tick=[int]$job.startTick;work_giver=[string]$job.workGiverDef;player_forced=([string]$job.playerForced -eq 'True');driver=[string]$driver.Class;driver_start_tick=[int]$driver.startTick;toil_index=[int]$driver.curToilIndex;ticks_left=[int]$driver.ticksLeftThisToil}
 skills=@($p.SelectNodes('skills/skills/li')|ForEach-Object{[ordered]@{def=[string]$_.def;level=(Numeric $_ 'level');xp_since_level=(Numeric $_ 'xpSinceLastLevel');xp_since_midnight=(Numeric $_ 'xpSinceMidnight');passion=if($_.SelectSingleNode('passion')){[string]$_.passion}else{'None'}}})
 work_priority_values=@($p.SelectNodes('workSettings/priorities/vals/li')|ForEach-Object{[int]$_.InnerText});carried=@($p.SelectNodes('carryTracker/innerContainer/innerList/li')|ForEach-Object{Item $_});traits=@($p.SelectNodes('story/traits/allTraits/li')|ForEach-Object{[ordered]@{def=[string]$_.def;degree=(Numeric $_ 'degree')}})}
}|Sort-Object {$_.id})
$medicines=@($map.SelectNodes('.//*[id and (def="MedicineHerbal" or def="MedicineIndustrial" or def="MedicineUltratech")]')|ForEach-Object{Item $_}|Sort-Object {$_.id})
$beds=@($map.SelectNodes('./things/thing[def="Bed"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;medical=([string]$_.medical -eq 'True');spawned_tick=[int]$_.spawnedTick}}|Sort-Object {$_.id})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;pawns=$pawns;medicines=$medicines;beds=$beds;scope='Read-only explicit XML. Current-map Humans, their hediff body indices, field-presence markers, jobs, skills, work vectors, and current-map medicine/beds. Missing numeric fields default zero except tendTicksLeft=-1; missing boolean false. Fields not applicable to a hediff retain present=false and do not establish a tend state. Computed HP, efficiency, capacities, bleeding and part names are separate UI/static observations, never inferred as serialized game values.'}|ConvertTo-Json -Depth 25
